-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            active_border   = { colors = {"rgba(33ccffee)", "rgba(00ff99ee)"}, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        -- Resize windows by hovering a window edge/border and dragging — the cursor
        -- turns into a resize arrow. ON by default. Toggle live with SUPER+SHIFT+B,
        -- or set this to false here to disable it permanently.
        resize_on_border = true,
        hover_icon_on_border = true,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 14,             -- was 10 — smoother macOS-like rounding
        rounding_power = 2.5,

        -- Subtle inactive-window fade — gives foreground focus without harshness
        active_opacity   = 1.0,
        inactive_opacity = 0.94,

        shadow = {
            enabled      = true,
            range        = 10,           -- moderate, doesn't spill into dock hover zone
            render_power = 3,
            color        = 0xcc0a0a0a,
            offset       = { 0, 4 },
        },

        -- Frosted glass but calmer — 5/2 keeps GPU cool and stops paint cascades
        blur = {
            enabled       = true,
            size          = 5,
            passes        = 2,
            vibrancy      = 0.20,
            new_optimizations = true,
            xray          = false,
            noise         = 0.02,
            contrast      = 1.05,
            brightness    = 1.0,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
-- fast start, long soft landing: workspace slides and window moves
hl.curve("pop",            { type = "bezier", points = { {0.16, 1},    {0.3, 1}     } })

-- Default springs
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true,  speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 4.1,  spring = "easy",         style = "popin 87%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 1.49, bezier = "easeInOutCubic", style = "popin 87%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 1.5,  bezier = "easeInOutCubic", style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 1.39, bezier = "almostLinear" })
-- Workspaces slide sideways, the same way the 3-finger swipe moves them
-- (a vertical slide made the horizontal swipe drag the screen up and down)
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 3.5,  bezier = "pop", style = "slide" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 3.5,  bezier = "pop", style = "slide" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 3.5,  bezier = "pop", style = "slide" })
hl.animation({ leaf = "specialWorkspace",    enabled = true, speed = 3.0, bezier = "easeOutQuint", style = "slidefadevert 50%" })
hl.animation({ leaf = "specialWorkspaceIn",  enabled = true, speed = 3.0, bezier = "easeOutQuint", style = "slidefadevert 50%" })
hl.animation({ leaf = "specialWorkspaceOut", enabled = true, speed = 2.0, bezier = "easeOutQuint", style = "slidefadevert 50%" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

